// Remove emojis (and related invisible characters) from a string, if present
function removeEmojis(text) {
  if (typeof text !== 'string') return text;
  return text
    .replace(/\p{Extended_Pictographic}/gu, '') // covers virtually all emoji
    .replace(/[\u{1F1E6}-\u{1F1FF}]/gu, '')      // regional indicator letters (flag emojis)
    .replace(/\u200D/g, '')                       // zero-width joiner used in combined emojis
    .replace(/\uFE0F/g, '')                       // emoji variation selector
    .replace(/[ \t]{2,}/g, ' ')                   // collapse extra spaces left behind
    .trim();
}

// Strip emojis from every text field in the item's JSON, if any exist
if ($input.item.json) {
  for (const key of Object.keys($input.item.json)) {
    if (typeof $input.item.json[key] === 'string') {
      $input.item.json[key] = removeEmojis($input.item.json[key]);
    }
  }
}

// Then prepare the voice note binary as before
if ($input.item.binary && $input.item.binary.data) {
  $input.item.binary.data.fileName = 'voice_note.opus';
  $input.item.binary.data.fileExtension = 'opus';
  $input.item.binary.data.mimeType = 'audio/ogg';
}

return $input.item;

const raw = 'PUT_YOUR_BASE64_ENCODED_MOODLE_TOKEN_HERE';

const decoded = Buffer.from(decodeURIComponent(raw), 'base64').toString('utf8');
const token = decoded.split(':::')[1];

const call = (wsfunction, params = {}) => this.helpers.httpRequest({
  method: 'GET',
  url: 'https://moodle.najah.edu/webservice/rest/server.php',
  qs: {
    wstoken: token,
    wsfunction,
    moodlewsrestformat: 'json',
    ...params
  },
  json: true,
});

const courses = await call('core_enrol_get_users_courses', {
  userid: 25688
});

const out = [];

for (const c of courses) {
  const sections = await call('core_course_get_contents', {
    courseid: c.id
  });

  for (const sec of sections) {
    for (const m of (sec.modules || [])) {
      if (m.modname === 'forum' || m.modname === 'url') continue;

      // تصفية الملفات لتأخذ فقط ملفات الـ PDF
      const pdfFiles = (m.contents || []).filter(f => 
        f.type === 'file' && f.filename && f.filename.toLowerCase().endsWith('.pdf')
      );

      // يتجاهل الموديول إذا لم يحتوِ على أي ملف PDF
      if (pdfFiles.length === 0) continue;

      const t = Math.max(...pdfFiles.map(f => f.timemodified || 0));

      // استخراج أسماء الملفات وروابطها المباشرة مع إضافة التوكن للتحميل المباشر
      const fileNames = pdfFiles.map(f => f.filename);
      const fileUrls = pdfFiles.map(f => f.fileurl ? `${f.fileurl}&token=${token}` : '');

      out.push({
        course: c.fullname,
        section: sec.name,
        files: fileNames,
        // إرجاع الرابط الأول كـ Text أو كمصفوفة في حال وجود أكثر من ملف بالموديول
        file_url: fileUrls.length === 1 ? fileUrls[0] : fileUrls,
        date: t
          ? new Date(t * 1000).toISOString().slice(0, 10)
          : null,
        ts: t,
      });
    }
  }
}

// ترتيب الملفات من الأحدث إلى الأقدم
out.sort((a, b) => b.ts - a.ts);

return out.slice(0, 100).map(item => ({ json: item }));

// ============================================================
// 1) قراءة البيانات
// ============================================================
const moodleItems = $('Get Files From Moodle').all().map(item => item.json);
const sheetRows = $('Get row(s) in sheet').all();

// أسماء الملفات الموجودة سابقاً في الشيت
const sheetFileNames = sheetRows.map(item => item.json.File_Name);

// أكبر ID موجود حالياً بالشيت (لو ما في، نبدأ من 1)
const existingIds = sheetRows
  .map(item => parseInt(item.json.ID, 10))
  .filter(n => !isNaN(n));

let nextId = existingIds.length > 0 ? Math.max(...existingIds) + 1 : 1;


// ============================================================
// 2) دالة استخراج اسم الملف
// ============================================================
const getFileName = (item) =>
  Array.isArray(item.files) ? item.files[0] : (item.files || item.Text || '');


// ============================================================
// 3) تصفية الملفات الجديدة والقديمة
// ============================================================
const newFiles = moodleItems.filter(file => !sheetFileNames.includes(getFileName(file)));
const existingFiles = moodleItems.filter(file => sheetFileNames.includes(getFileName(file)));


// ============================================================
// 4) الملخصات النصية (تبقى كما هي، مفيدة للـ AI Agent كـ fallback فقط)
// ============================================================
const newFilesSummary = newFiles
  .map((f, i) =>
    `${i + 1}. اسم الملف: ${getFileName(f)}\n` +
    `   المادة: ${f.course || 'غير محدد'}\n` +
    `   السكشن: ${f.section || 'غير محدد'}\n` +
    `   الرابط: ${f.file_url || 'لا يوجد'}`
  )
  .join('\n\n');

const existingFilesSummary = existingFiles
  .map(f => `- ${getFileName(f)} (المادة: ${f.course || 'غير محدد'}, الرابط: ${f.file_url || 'لا يوجد'})`)
  .join('\n');

const allFilesSummary = moodleItems
  .map(f => `- ${getFileName(f)} (المادة: ${f.course || 'غير محدد'}, الرابط: ${f.file_url || 'لا يوجد'})`)
  .join('\n');


// ============================================================
// 5) استخراج request_type من مخرجات نود الموديل
// ============================================================
let requestType = null;

try {
  const modelOutput = $('Analyze Text').first().json;
  const rawText = modelOutput.content.parts[0].text;
  const parsed = JSON.parse(rawText);
  requestType = parsed.request_type || null;
} catch (e) {
  requestType = null;
}


// ============================================================
// 6) item منفصل لكل ملف جديد (مع ID فريد متسلسل)
// ============================================================
const fileItems = newFiles.map((f) => {
  const item = {
    json: {
      ID: nextId,
      File_Name: getFileName(f),
      Course_Name: f.course || 'غير محدد',
      Section_Name: f.section || 'غير محدد',
      Date: f.date || '',
      URL: f.file_url || '',
      has_new_files: newFiles.length > 0,
      new_files_count: newFiles.length,
      new_files_summary: newFilesSummary || "لا توجد ملفات جديدة",
      existing_files_summary: existingFilesSummary || "لا توجد ملفات سابقة",
      all_files_summary: allFilesSummary,
      item_type: 'file'
    }
  };

  nextId++; // نزيد الرقم لكل ملف جديد بالتسلسل
  return item;
});


// ============================================================
// 7) item الـ request_type لوحده
// ============================================================
const requestTypeItem = {
  json: {
    request_type: requestType,
    item_type: 'meta'
  }
};


// ============================================================
// 8) المخرجات
// ============================================================
if (fileItems.length === 0) {
  return [
    {
      json: {
        ID: null,
        File_Name: null,
        has_new_files: false,
        new_files_count: 0,
        new_files_summary: "لا توجد ملفات جديدة",
        existing_files_summary: existingFilesSummary || "لا توجد ملفات سابقة",
        all_files_summary: allFilesSummary,
        item_type: 'file'
      }
    },
    requestTypeItem
  ];
}

return [...fileItems, requestTypeItem];

const sheetRows = $('Get row(s) in sheet').all();
// الملفات الجديدة بعد ما انضافت للشيت (فيها ID الحقيقي من Code in JavaScript4)
const appendedRows = $('Append or update row in sheet').all().map(item => item.json);

const getCleanFileName = (item) => {
  let rawName = item.File_Name || item.files || item.Text || '';
  if (Array.isArray(rawName)) rawName = rawName[0];
  return String(rawName).replace(/https?:\/\/[^\s]+/g, '').trim();
};

// يبني كائن ملف نظيف، أو null إذا الصف غير صالح (بدون اسم ملف حقيقي)
const buildFileEntry = (item) => {
  const fileName = getCleanFileName(item);
  const courseName = (item.Course_Name || item.course || '').trim();
  const id = item.ID ?? null;

  // نتجاهل أي صف: اسم الملف فاضي، أو "**"، أو بدون ID حقيقي
  if (!fileName || fileName === '**' || fileName === '*' || !id) return null;

  return {
    id,
    fileName,
    // إذا ما فيه اسم مادة حقيقي، نحطه ضمن "غير مصنف" بدل "مادة عامة"
    courseName: courseName || 'غير مصنف'
  };
};

// تجميع قائمة ملفات حسب المادة، وبناء النص النهائي جاهز
const groupBySubject = (fileList) => {
  const cleanList = fileList
    .map(buildFileEntry)
    .filter(Boolean); // إزالة كل القيم null (الصفوف الفاضية)

  if (cleanList.length === 0) return "📭 لا توجد ملفات مطابقة حالياً.";

  // تجميع حسب اسم المادة
  const groups = {};
  for (const f of cleanList) {
    if (!groups[f.courseName]) groups[f.courseName] = [];
    groups[f.courseName].push(f);
  }

  let output = '';
  for (const subject of Object.keys(groups)) {
    output += `📚 المادة: ${subject}\n`;
    for (const f of groups[subject]) {
      output += `(${f.id}) 📄 *${f.fileName}*\n`;
    }
    output += '\n';
  }

  return output.trim();
};

const newRawFiles = appendedRows.filter(f => f.item_type !== 'meta');
const existingRawFiles = sheetRows.map(r => r.json);

// 3 نصوص جاهزة تماماً، مجمعة حسب المادة، بدون الحاجة لأي معالجة إضافية من الموديل
const newFilesSummary = groupBySubject(newRawFiles);
const existingFilesSummary = groupBySubject(existingRawFiles);
const allFilesSummary = groupBySubject([...newRawFiles, ...existingRawFiles]);

return [{
  json: {
    new_files_count: newRawFiles.filter(buildFileEntry).length,
    new_files_summary: newFilesSummary,
    existing_files_summary: existingFilesSummary,
    all_files_summary: allFilesSummary
  }
}];

const modelOutput = $('Basic LLM Chain1').first().json;

let parsed;
try {
  // الناتج في حقل text، وننظفه من أسوار ```json إن وُجدت
  const rawText = String(modelOutput.text ?? '')
    .replace(/```json|```/g, '')
    .trim();
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = { intent_type: 'text_request', selected_option: null, user_query: '' };
}

let selectedOptions = parsed.selected_option;

// توحيد الشكل ليكون دائماً مصفوفة
if (selectedOptions === null || selectedOptions === undefined) {
  selectedOptions = [];
} else if (!Array.isArray(selectedOptions)) {
  selectedOptions = [selectedOptions];
}

// تحويل كل قيمة لرقم صحيح
const numericIds = selectedOptions
  .map(v => parseInt(String(v).replace(/[^\d]/g, ''), 10))
  .filter(n => !isNaN(n));

return [{
  json: {
    intent_type: parsed.intent_type,
    selected_ids: numericIds,
    user_query: parsed.user_query
  }
}];

const selectedIds = $('Extracting text').first().json.selected_ids;
const sheetRows = $('Get row(s) in sheet1').all().map(item => item.json);

const matchedFiles = sheetRows
  .filter(row => selectedIds.includes(parseInt(row.ID, 10)))
  .sort((a, b) => parseInt(a.ID, 10) - parseInt(b.ID, 10)); // ترتيب تصاعدي حسب ID

const totalCount = matchedFiles.length;

// كشف اللغة من رسالة المستخدم الأصلية
const userQuery = $('Extracting text').first().json.user_query || '';
const language = /[\u0600-\u06FF]/.test(userQuery) ? 'ar' : 'en';

if (totalCount === 0) {
  return [{
    json: {
      found: false,
      File_Name: null,
      URL: null,
      total_files: 0,
      language: language,
      message: "❌ لم يتم العثور على ملفات بهذه الأرقام."
    }
  }];
}

return matchedFiles.map((f, index) => ({
  json: {
    found: true,
    File_Name: f.File_Name,
    URL: f.URL,
    ID: f.ID,
    file_index: index + 1,
    total_files: totalCount,
    language: language   // 'ar' أو 'en'
  }
}));
